-- docs/audits/question-purge-2026-09-10/apply-approved-removals.sql
-- Authorized removal of #86, #132, #166 and #172. Preserve #144 and the generated backlog.
-- Uses the existing removed=true semantics. All changes are transactional.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '20s';
LOCK TABLE public.comments IN SHARE MODE;
CREATE TEMP TABLE removal_ids (id bigint PRIMARY KEY) ON COMMIT DROP;
INSERT INTO removal_ids VALUES (86),(132),(166),(172);
CREATE TEMP TABLE before_preserved ON COMMIT DROP AS SELECT to_jsonb(q) AS row FROM public.questions q WHERE id=144;
CREATE TEMP TABLE before_backlog ON COMMIT DROP AS SELECT id,removed,flagged FROM public.questions WHERE data->>'source'='chorus' AND flagged IS TRUE AND removed IS NOT TRUE;
CREATE TEMP TABLE affected_categories (id integer PRIMARY KEY) ON COMMIT DROP;
INSERT INTO affected_categories WITH RECURSIVE a AS (
 SELECT DISTINCT tag_id AS id FROM public.question_category_tags WHERE question_id IN (SELECT id FROM removal_ids)
 UNION SELECT c.parent_id FROM public.question_categories c JOIN a ON a.id=c.id WHERE c.parent_id IS NOT NULL
) SELECT id FROM a;
DO $guard$
DECLARE unexpected integer;
BEGIN
 PERFORM q.id FROM public.questions q JOIN removal_ids r ON r.id=q.id FOR UPDATE OF q;
 PERFORM c.id FROM public.question_categories c JOIN affected_categories a ON a.id=c.id FOR UPDATE OF c;
 IF (SELECT count(*) FROM public.questions q JOIN removal_ids r ON r.id=q.id WHERE q.removed IS FALSE AND q.starter_rank IS NULL AND cardinality(q.pinned_comment_ids)=0) <> 4 THEN RAISE EXCEPTION 'Question state changed; abort removal'; END IF;
 IF EXISTS (
  SELECT 1 FROM jsonb_to_recordset($expected$[{"id":86,"url":"what-are-you-thinking","author_id":"9ce7ff91-d7f8-4397-b00d-8716e335aaee","removed":false,"flagged":false,"updated_at":"2023-10-01T02:43:25.776+00:00"},{"id":132,"url":"longest-stayed-awake-working-project-passionate-9","author_id":"9ce7ff91-d7f8-4397-b00d-8716e335aaee","removed":false,"flagged":false,"updated_at":"2023-12-02T05:54:41.069+00:00"},{"id":166,"url":"whats-biggest-lesson-youve-learned-year-2024","author_id":"9ce7ff91-d7f8-4397-b00d-8716e335aaee","removed":false,"flagged":true,"updated_at":"2024-06-14T22:44:05.119+00:00"},{"id":172,"url":"main-fear-trump-getting-elected","author_id":"9ce7ff91-d7f8-4397-b00d-8716e335aaee","removed":false,"flagged":true,"updated_at":"2024-09-06T04:43:43.439+00:00"}]$expected$::jsonb) AS e(id bigint,url text,author_id uuid,removed boolean,flagged boolean,updated_at timestamptz)
  LEFT JOIN public.questions q ON q.id=e.id
  WHERE q.id IS NULL OR q.url IS DISTINCT FROM e.url OR q.author_id IS DISTINCT FROM e.author_id OR q.removed IS DISTINCT FROM e.removed OR q.flagged IS DISTINCT FROM e.flagged OR q.updated_at IS DISTINCT FROM e.updated_at
 ) THEN RAISE EXCEPTION 'Question changed since backup'; END IF;
 WITH RECURSIVE thread AS (
  SELECT c.id,c.author_id,c.removed,ARRAY[c.id] AS seen FROM public.comments c WHERE c.parent_type='question' AND c.parent_id IN (SELECT id FROM removal_ids)
  UNION ALL SELECT c.id,c.author_id,c.removed,t.seen||c.id FROM public.comments c JOIN thread t ON t.id=c.parent_id WHERE c.parent_type='comment' AND NOT c.id=ANY(t.seen)
 ) SELECT count(*) INTO unexpected FROM thread t WHERE NOT t.removed AND (t.author_id IS NULL OR t.author_id NOT IN (SELECT id FROM public.profiles WHERE lower(email) IN ('djwayne3@gmail.com','djwayne35@gmail.com')));
 IF unexpected<>0 THEN RAISE EXCEPTION 'New outside participation found; abort removal'; END IF;
 IF EXISTS(SELECT 1 FROM public.question_feature_runs WHERE question_id IN (SELECT id FROM removal_ids) AND status='active') OR EXISTS(SELECT 1 FROM public.question_distribution_settings WHERE fallback_question_id IN (SELECT id FROM removal_ids)) THEN RAISE EXCEPTION 'An approved question is currently featured'; END IF;
 IF EXISTS(SELECT 1 FROM public.question_categories c JOIN affected_categories a ON a.id=c.id WHERE c.intro_status='processing') THEN RAISE EXCEPTION 'Category generation currently running'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_to_recordset($categories$[{"id":34,"intro_updated_at":"2026-07-19T19:51:59.482+00:00","intro_markdown":"Political Ideologies explores the beliefs and values people use to understand power, government, parties, and public life. Questions here ask what people fear or hope for in political leadership, where parties fall short, and what evidence or experience might change a political opinion.\n\nRather than treating ideology as a label alone, this category looks at the assumptions underneath a take: how much trust someone places in institutions, which outcomes they prioritize, and how personal experience shapes reactions to candidates, conflict, and social change. Browse the questions to compare perspectives, explain your own reasoning, and notice where people with different political commitments may still share concerns."},{"id":57,"intro_updated_at":"2026-07-19T19:57:18.873+00:00","intro_markdown":"Personal Growth is about the ways people examine their habits, beliefs, and choices—and decide what they want to change. Questions here invite reflection on routines, stress, disagreements, advice, ambition, and the experiences that reshape a person’s direction.\n\nGrowth does not look the same for everyone. Some people focus on practical habits; others reconsider a long-held opinion, learn from a difficult relationship, or make sense of a turning point. Browse the questions to share lessons that have stayed with you, name what you are working on now, and compare how different personalities approach self-awareness, resilience, and change. The aim is honest reflection, not a single formula for becoming your “best self.”"},{"id":33,"intro_updated_at":"2026-07-19T20:54:32.18+00:00","intro_markdown":"This collection explores how people engage with electoral democracy, from casting ballots to building careers in public service. Questions touch on voter decision-making, leadership assessments, and practical pathways for young people entering government and policy work.\n\nDiscussions reflect individual perspectives on candidate evaluation, civic participation, and the mechanics of representation—from grassroots organizing to national races. Whether examining specific political figures or broader themes of accountability and representation, these conversations capture how citizens think about their role in shaping political outcomes."},{"id":35,"intro_updated_at":"2026-07-19T20:06:13.323+00:00","intro_markdown":"Government Systems explores how people understand political leadership, parties, elections, and the decisions made in the public's name. Questions here invite discussion about presidential candidates, foreign-policy motives, the strengths and failures of political parties, and the fears that shape people's reactions to political change.\n\nThe category also asks how political beliefs develop and what evidence, experience, or conversation might cause someone to reconsider a position. For people interested in public service, it includes practical reflection on beginning a political career. Browse the questions to compare assumptions, explain the values behind a viewpoint, and examine how trust, uncertainty, and accountability influence judgments about government."},{"id":60,"intro_updated_at":"2026-07-19T20:54:01.072+00:00","intro_markdown":"Life brings moments that shape who we become, from seasonal celebrations to transformative milestones. This collection explores the questions that arise during pivotal transitions—whether you're reflecting on lessons learned over the past year, navigating holiday traditions, or standing at the crossroads of major life decisions.\n\nYou'll find conversations around educational pathways and career uncertainty for young adults, alongside wisdom for raising children and building family connections. These discussions capture the essence of human experience: growth through challenge, celebration of achievements, and the continuous search for meaningful guidance during life's most significant chapters."},{"id":14,"intro_updated_at":"2026-07-19T19:56:39.304+00:00","intro_markdown":"Personal Interests and Lifestyle explores the choices, routines, challenges, and experiences that shape how people live. Questions range from ideal mornings and habits you wish you had started sooner to the lessons, decisions, and turning points that change how you see yourself.\n\nBrowse four related areas: Personal Growth, Daily Routines, Personal Challenges, and Life Events. Together, they invite reflection on self-awareness, stress, ambition, resilience, and the advice people carry into new stages of life. Share the practices that help you, describe what you are still figuring out, and compare how different people approach growth without assuming there is one right way to build a meaningful life."},{"id":8,"intro_updated_at":"2026-07-19T19:49:53.091+00:00","intro_markdown":"Politics and Policy brings together questions about elections, political beliefs, government, and diplomacy. Explore how people interpret leaders and parties, what shapes voting decisions, and which fears or priorities influence political opinions.\n\nThe questions also invite practical and personal perspectives: what might change someone’s mind, how government systems earn trust, and what it takes to pursue a career in politics. Browse the related topics to compare viewpoints on Elections and Voting, Political Ideologies, Government Systems, and Diplomacy. The goal is not to settle every debate, but to make the assumptions, values, and lived experiences behind political takes easier to understand."},{"id":1,"intro_updated_at":"2026-07-19T18:49:09.879+00:00","intro_markdown":"Political, Social, and Economic Affairs gathers questions about how public decisions, cultural forces, and working life shape what people believe and fear. There are no questions filed directly under this broad category yet; the conversation lives in its Politics and Policy, Society and Culture, and Economy and Work sections.\n\nAcross those sections, people wrestle with elections, political persuasion, party conflict, war, public violence, legal consequences, social impact, career paths in politics, and the pressures surrounding work and the economy. The goal here is not to settle those debates, but to reveal the motives, loyalties, anxieties, and values beneath different positions. Browse the questions below to compare how nine personality perspectives interpret power, community, risk, fairness, and change."},{"id":3,"intro_updated_at":"2026-07-19T19:56:04.762+00:00","intro_markdown":"Personal Life and Wellness brings together questions about the habits, relationships, and choices that shape everyday life. Explore how people build routines, handle stress, pursue interests, and reflect on the experiences that influence who they are.\n\nThe category connects three broad areas: Personal Interests and Lifestyle, Relationships, and Health and Wellness. Across them, questions invite honest perspectives on personal growth, family and friendship, self-awareness, communication, and the tension between the life someone has and the life they want. Browse the related topics to share what has helped you, compare different approaches, and understand how other people define balance, connection, and well-being."}]$categories$::jsonb) e(id integer,intro_updated_at timestamptz,intro_markdown text) JOIN public.question_categories c ON c.id=e.id WHERE c.intro_updated_at IS DISTINCT FROM e.intro_updated_at OR c.intro_markdown IS DISTINCT FROM e.intro_markdown) THEN RAISE EXCEPTION 'Category copy changed since backup'; END IF;
END;
$guard$;
UPDATE public.questions SET removed=TRUE,updated_at=NOW() WHERE id IN (SELECT id FROM removal_ids);
-- Refresh editorial context from the public question set. This metadata is not
-- used for displayed counts; category pages compute those from live mappings.
CREATE TEMP TABLE category_tree ON COMMIT DROP AS
WITH RECURSIVE a AS (
 SELECT id AS ancestor_id,id AS descendant_id FROM public.question_categories
 UNION ALL SELECT a.ancestor_id,c.id FROM a JOIN public.question_categories c ON c.parent_id=a.descendant_id
) SELECT * FROM a;
CREATE TEMP TABLE live_category_questions ON COMMIT DROP AS
SELECT DISTINCT t.ancestor_id,q.id,q.question,q.question_formatted,q.created_at
FROM category_tree t JOIN public.question_category_tags qt ON qt.tag_id=t.descendant_id
JOIN public.questions q ON q.id=qt.question_id WHERE q.removed IS FALSE AND q.flagged IS NOT TRUE;
UPDATE public.question_categories c SET
 intro_context=(COALESCE(c.intro_context,'{}'::jsonb)-'contextHash')||jsonb_build_object(
  'directQuestionCount',(SELECT count(DISTINCT q.id) FROM public.question_category_tags t JOIN public.questions q ON q.id=t.question_id WHERE t.tag_id=c.id AND q.removed IS FALSE AND q.flagged IS NOT TRUE),
  'subtreeQuestionCount',(SELECT count(*) FROM live_category_questions l WHERE l.ancestor_id=c.id),
  'sampleQuestionIds',COALESCE((SELECT jsonb_agg(s.id ORDER BY s.created_at DESC,s.id DESC) FROM (SELECT * FROM live_category_questions l WHERE l.ancestor_id=c.id ORDER BY created_at DESC,id DESC LIMIT 8) s),'[]'::jsonb),
  'sampleQuestionTitles',COALESCE((SELECT jsonb_agg(COALESCE(s.question_formatted,s.question) ORDER BY s.created_at DESC,s.id DESC) FROM (SELECT * FROM live_category_questions l WHERE l.ancestor_id=c.id ORDER BY created_at DESC,id DESC LIMIT 8) s),'[]'::jsonb),
  'childCategories',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',child.id,'name',child.category_name,'directQuestionCount',(SELECT count(DISTINCT q.id) FROM public.question_category_tags t JOIN public.questions q ON q.id=t.question_id WHERE t.tag_id=child.id AND q.removed IS FALSE AND q.flagged IS NOT TRUE),'subtreeQuestionCount',(SELECT count(*) FROM live_category_questions l WHERE l.ancestor_id=child.id)) ORDER BY child.id) FROM public.question_categories child WHERE child.parent_id=c.id AND EXISTS(SELECT 1 FROM live_category_questions l WHERE l.ancestor_id=child.id)),'[]'::jsonb),
  'questionRemovalAudit','2026-09-10-approved-four','questionContextRefreshedAt',NOW())
WHERE c.id IN (SELECT id FROM affected_categories);
UPDATE public.question_categories c SET
 intro_markdown=copy.intro,intro_description=copy.description,intro_status='completed',
 intro_source=CASE WHEN c.intro_generated_at IS NOT NULL OR c.intro_source IN ('ai','ai_edited') THEN 'ai_edited' ELSE 'manual' END,
 intro_updated_at=NOW(),intro_reviewed_at=NULL,
 intro_context=(c.intro_context-'reviewedAt'-'reviewedBy'-'staleAt'-'semanticTerms')||jsonb_build_object('lastError',NULL,'editedAt',NOW(),'editedBy','Codex; user-authorized question cleanup')
FROM jsonb_to_recordset($copy$[{"id":60,"intro":"Life Events brings together questions about decisions and advice that matter at different stages of life. The current discussions cover choosing a college direction, lessons from parenting, and looking back on the best decision you have made.\n\nShare an experience that changed your direction or advice that helped when the next step was uncertain. Different people can face a similar choice and value very different things about the outcome.","description":"Questions about college uncertainty, parenting advice, and the decisions that change a life."},{"id":33,"intro":"Elections and Voting currently has one discussion: advice for a recent high school graduate who wants to become a politician. It is a starting point for talking about entering public life and what someone should learn along the way.\n\nShare what you wish you had known when considering public service, or an experience that changed how you think about a political career.","description":"Share advice for a recent high school graduate who wants to become a politician."},{"id":35,"intro":"Government Systems brings together questions about the problems with political parties, what could change a political opinion, and advice for someone considering a career in politics.\n\nThese discussions start with personal judgments and experiences. Explain what you think parties get wrong, which evidence would make you reconsider your position, or what a young person should understand before entering public life. Comparing the reasons behind those answers can reveal different expectations of government and public service.","description":"Questions about political parties, changing your mind politically, and beginning a career in public service."},{"id":34,"intro":"Political Ideologies gathers questions about political parties, changing political beliefs, and starting a career in public life. The discussions invite you to explain where your views come from and what might make you reconsider them.\n\nDescribe a problem you see in a political party, an experience that challenged an opinion, or advice you would give someone interested in politics. The useful differences often lie in the reasons behind an answer: what people trust, what they prioritize, and what they have lived through.","description":"Explore political beliefs through questions about parties, changing your mind, and advice for an aspiring politician."},{"id":8,"intro":"Politics and Policy brings together questions about political parties, changing political beliefs, and finding a path into public service. Browse the related categories to compare how people explain their views and what they would tell someone considering a political career.\n\nAn answer can start with a problem you see, a moment that changed your opinion, or something you learned through experience. The aim is to understand the reasons behind different takes and make room for a thoughtful response.","description":"Explore questions about political parties, changing political beliefs, and starting a career in public service."},{"id":1,"intro":"Political, Social, and Economic Affairs collects discussions about public life and the ways people relate to one another. The current questions are in Politics and Policy and Society and Culture. They include the problems with political parties and social media, what could change a political opinion, and advice for someone interested in becoming a politician.\n\nBrowse those discussions to share an experience, explain a judgment, or consider why someone else sees the same issue differently.","description":"Questions about political beliefs, social media, public life, and the experiences behind different opinions."}]$copy$::jsonb) AS copy(id integer,intro text,description text)
WHERE c.id=copy.id;
DO $verify$
BEGIN
 IF (SELECT count(*) FROM public.questions WHERE id IN (86,132,166,172) AND removed IS TRUE)<>4 THEN RAISE EXCEPTION 'Removal verification failed'; END IF;
 IF (SELECT to_jsonb(q) FROM public.questions q WHERE id=144) IS DISTINCT FROM (SELECT row FROM before_preserved) THEN RAISE EXCEPTION 'Preserved question changed'; END IF;
 IF EXISTS(SELECT 1 FROM before_backlog b LEFT JOIN public.questions q ON q.id=b.id WHERE q.id IS NULL OR q.removed IS DISTINCT FROM b.removed OR q.flagged IS DISTINCT FROM b.flagged) THEN RAISE EXCEPTION 'Generated backlog changed'; END IF;
END;
$verify$;
SELECT json_build_object('removed_ids',(SELECT json_agg(id ORDER BY id) FROM public.questions WHERE id IN (86,132,166,172) AND removed IS TRUE),'visible_questions',(SELECT count(*) FROM public.questions WHERE removed IS NOT TRUE AND flagged IS NOT TRUE),'preserved_question_144',EXISTS(SELECT 1 FROM public.questions WHERE id=144 AND removed IS FALSE AND flagged IS NOT TRUE),'unchanged_generated_backlog',(SELECT count(*) FROM before_backlog),'category_contexts_updated',(SELECT count(*) FROM affected_categories),'category_intros_updated',6);
COMMIT;
